#include <bits/stdc++.h>
using namespace std;

int main() {
    long long D;
    if (!(cin >> D)) return 0;

    // O percurso: 3 km do emissor ate o anel (circunferencia 8 km),
    // depois voltas no anel ate o ponto de saida de um sensor.
    // Cada sensor tem um unico ponto de saida no anel, logo um unico
    // residuo de D modulo 8:
    //   sensor 1: D % 8 == 6  (ex.: D = 6)
    //   sensor 2: D % 8 == 7  (ex.: D = 23)
    //   sensor 3: D % 8 == 0  (ex.: D = 9192)
    long long r = (D - 3) % 8;
    if (r < 0) r += 8;

    if (r == 3) cout << 1 << "\n";
    else if (r == 4) cout << 2 << "\n";
    else cout << 3 << "\n";

    return 0;
}
